package com.gymmind.nutrition.infrastructure.persistence; import com.gymmind.nutrition.domain.model.NutritionRecord; import com.gymmind.nutrition.domain.repository.NutritionRecordRepository; import org.springframework.stereotype.Repository; @Repository class JpaNutritionRecordRepository implements NutritionRecordRepository { final SpringDataNutritionRecordRepository d; JpaNutritionRecordRepository(SpringDataNutritionRecordRepository d){this.d=d;} public NutritionRecord save(NutritionRecord r){return d.save(r);} }
